-- Generated by Supabase CLI 20261105132931; normalized to repository numbering.
-- Apply after 4011 has committed. Saved gems and private collection membership
-- are one transactional bookmark. No public read policies are widened.
BEGIN;
CREATE SCHEMA IF NOT EXISTS collection_internal;
REVOKE ALL ON SCHEMA collection_internal FROM PUBLIC, anon, authenticated;

-- Import old bookmarks once, preserving save order and existing custom filing.
INSERT INTO public.collections(owner_id,name,is_default,position)
 SELECT DISTINCT s.user_id,'Saved',true,0 FROM public.hidden_gem_saves s
 WHERE NOT EXISTS(SELECT 1 FROM public.collections c WHERE c.owner_id=s.user_id AND c.is_default)
 ON CONFLICT DO NOTHING;
INSERT INTO public.collection_items(collection_id,entity_type,entity_id,saved_at)
 SELECT c.id,'gem',s.gem_id,s.saved_at FROM public.hidden_gem_saves s
 JOIN public.collections c ON c.owner_id=s.user_id AND c.is_default
 WHERE NOT EXISTS(SELECT 1 FROM public.collection_items i JOIN public.collections owned ON owned.id=i.collection_id
   WHERE owned.owner_id=s.user_id AND i.entity_type='gem' AND i.entity_id=s.gem_id)
 ON CONFLICT(collection_id,entity_type,entity_id) DO NOTHING;

-- Internal trigger privileges are needed to update the shared aggregate; table
-- RLS still authorizes the originating write, and auth.uid is checked again.
CREATE OR REPLACE FUNCTION collection_internal.bridge_gem_bookmark() RETURNS trigger
 LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE saver uuid; gem uuid; collection uuid;
BEGIN
 IF TG_TABLE_NAME='collection_items' THEN
  IF (CASE WHEN TG_OP='DELETE' THEN OLD.entity_type ELSE NEW.entity_type END)::text<>'gem' THEN RETURN NULL; END IF;
  SELECT owner_id INTO saver FROM public.collections WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.collection_id ELSE NEW.collection_id END;
  -- A collection deleted directly by its owner leaves the bookmark in Saved
  -- gems. The API moves its contents to the default before deleting a folder.
  IF saver IS NULL THEN RETURN NULL; END IF;
  gem=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;
 ELSE
  saver=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  gem=CASE WHEN TG_OP='DELETE' THEN OLD.gem_id ELSE NEW.gem_id END;
 END IF;
 IF auth.uid() IS NOT NULL AND auth.uid()<>saver THEN RAISE EXCEPTION 'gem_bookmark_owner_mismatch'; END IF;
 -- All users' writes for a gem share a lock so the count cannot lose updates.
 PERFORM pg_advisory_xact_lock(hashtextextended('gem-bookmark:'||gem::text,0));
 IF TG_TABLE_NAME='collection_items' THEN
  IF TG_OP='INSERT' THEN
   INSERT INTO public.hidden_gem_saves(user_id,gem_id,saved_at) VALUES(saver,gem,NEW.saved_at) ON CONFLICT DO NOTHING;
  ELSIF NOT EXISTS(SELECT 1 FROM public.collection_items i JOIN public.collections c ON c.id=i.collection_id
    WHERE c.owner_id=saver AND i.entity_type='gem' AND i.entity_id=gem) THEN
   DELETE FROM public.hidden_gem_saves WHERE user_id=saver AND gem_id=gem;
  END IF;
 ELSE
  IF TG_OP='INSERT' THEN
   IF NOT EXISTS(SELECT 1 FROM public.collection_items i JOIN public.collections c ON c.id=i.collection_id
     WHERE c.owner_id=saver AND i.entity_type='gem' AND i.entity_id=gem) THEN
    INSERT INTO public.collections(owner_id,name,is_default,position) VALUES(saver,'Saved',true,0) ON CONFLICT DO NOTHING;
    SELECT id INTO STRICT collection FROM public.collections WHERE owner_id=saver AND is_default;
    INSERT INTO public.collection_items(collection_id,entity_type,entity_id,saved_at)
     VALUES(collection,'gem',gem,NEW.saved_at) ON CONFLICT DO NOTHING;
   END IF;
  ELSE
   DELETE FROM public.collection_items i USING public.collections c WHERE c.id=i.collection_id AND c.owner_id=saver AND i.entity_type='gem' AND i.entity_id=gem;
  END IF;
 END IF;
 UPDATE public.hidden_gems SET save_count=(SELECT count(*) FROM public.hidden_gem_saves WHERE gem_id=gem) WHERE id=gem;
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION collection_internal.bridge_gem_bookmark() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS collection_gem_bookmark_bridge ON public.collection_items;
CREATE TRIGGER collection_gem_bookmark_bridge AFTER INSERT OR DELETE ON public.collection_items FOR EACH ROW EXECUTE FUNCTION collection_internal.bridge_gem_bookmark();
DROP TRIGGER IF EXISTS hidden_gem_bookmark_bridge ON public.hidden_gem_saves;
CREATE TRIGGER hidden_gem_bookmark_bridge AFTER INSERT OR DELETE ON public.hidden_gem_saves FOR EACH ROW EXECUTE FUNCTION collection_internal.bridge_gem_bookmark();
CREATE OR REPLACE FUNCTION collection_internal.immutable_gem_bookmark_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_TABLE_NAME='hidden_gem_saves' THEN
  IF (NEW.gem_id,NEW.user_id) IS DISTINCT FROM (OLD.gem_id,OLD.user_id) THEN RAISE EXCEPTION 'remove_and_add_gem_bookmark'; END IF;
 ELSIF (OLD.entity_type::text='gem' OR NEW.entity_type::text='gem') AND
  (NEW.collection_id,NEW.entity_type,NEW.entity_id) IS DISTINCT FROM (OLD.collection_id,OLD.entity_type,OLD.entity_id) THEN RAISE EXCEPTION 'remove_and_add_gem_bookmark'; END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION collection_internal.immutable_gem_bookmark_identity() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS collection_gem_bookmark_identity ON public.collection_items;
CREATE TRIGGER collection_gem_bookmark_identity BEFORE UPDATE ON public.collection_items FOR EACH ROW EXECUTE FUNCTION collection_internal.immutable_gem_bookmark_identity();
DROP TRIGGER IF EXISTS hidden_gem_bookmark_identity ON public.hidden_gem_saves;
CREATE TRIGGER hidden_gem_bookmark_identity BEFORE UPDATE ON public.hidden_gem_saves FOR EACH ROW EXECUTE FUNCTION collection_internal.immutable_gem_bookmark_identity();
UPDATE public.hidden_gems g SET save_count=(SELECT count(*) FROM public.hidden_gem_saves s WHERE s.gem_id=g.id);
COMMIT;
